    @EventHandler( payloadType=UpdateUserEvent.class )
    public void handle( UpdateUserEvent event) {
    	LOGGER.info("handling UpdateUserEvent - " + event );
    	
	    User entity = new User();
            entity.setUserId( event.getUserId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setEmail( event.getEmail() );
            entity.setAgency( event.getAgency() );
            entity.setTeams( event.getTeams() );
            entity.setAdAccounts( event.getAdAccounts() );
            entity.setRole( event.getRole() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindUser( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllUser( entity );        
    }
    
