    /**
     * Method to retrieve the User via an UserPrimaryKey.
     * @param 	id Long
     * @return 	User
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public User handle( FindUserQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getUserId() );
    }
    
    /**
     * Method to retrieve a collection of all Users
     *
     * @param	query	FindAllUserQuery 
     * @return 	List<User> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<User> handle( FindAllUserQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindUser,
 * but only if the id matches
 *
 * @param		entity	User
 */
	protected void emitFindUser( User entity ) {
		LOGGER.info("handling emitFindUser" );
		
	    queryUpdateEmitter.emit(FindUserQuery.class,
	                            query -> query.getFilter().getUserId().equals(entity.getUserId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllUser
	 * 
	 * @param		entity	User
	 */
	protected void emitFindAllUser( User entity ) {
		LOGGER.info("handling emitFindAllUser" );
		
	    queryUpdateEmitter.emit(FindAllUserQuery.class,
	                            query -> true,
	                            entity);
	}

